      new_row <- dim_region_raw %>% filter(region_kod == "1384")
      
      if (nrow(new_row) == 0) {
        new_row <- dim_region_raw[1, , drop = FALSE]  # Copy structure
        new_row$region_kod <- "1384"
        new_row[, setdiff(names(new_row), "region_kod")] <- NA
      }
      
      dim_region <- bind_rows(dim_region, new_row)  # Add to dataset
    }
  }
  
  # Select specified columns, keeping original case
  selected_columns <- colnames(dim_region)[tolower(colnames(dim_region)) %in% gruppering]
  dim_region <- dim_region[, selected_columns, drop = FALSE]
  
  return(dim_region)
}
